<?php
declare(strict_types=1);
namespace SimpleMSPDoc\Tests\Integration;
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }

use SimpleMSPDoc\Core\Actor;
use SimpleMSPDoc\Modules\Audit\AuditService;
use SimpleMSPDoc\Modules\Assets\{TemplateService,AssetService,FieldValidator};
final class AssetTest extends DatabaseTestCase
{
 public function testCustomTypesAndArchivedFieldsKeepValues(): void {
  $this->schema();$a=new Actor($this->user(),'administrator','staff');$org=$this->org();$audit=new AuditService($this->db);$t=new TemplateService($this->db,$audit);$type=$t->create($a,['name'=>'Warranty','fields'=>[['name'=>'Count','type'=>'number','required'=>true],['name'=>'Covered','type'=>'boolean'],['name'=>'Due','type'=>'date'],['name'=>'Portal','type'=>'url'],['name'=>'Plan','type'=>'choice','options'=>['Basic','Pro']],['name'=>'Notes','type'=>'multiline'],['name'=>'Text','type'=>'text']]]);
  $fields=$t->get($type)['fields'];$values=[];foreach($fields as $f)$values[$f['id']]=match($f['field_type']){'number'=>'0','boolean'=>false,'date'=>'2027-01-01','url'=>'https://example.com','choice'=>'Pro','multiline'=>"a\nb",default=>'hello'};
  $s=new AssetService($this->db,$audit);$id=$s->create($a,$org,['title'=>'Asset','payload'=>['template_id'=>$type,'values'=>$values]]);$r=$s->get($a,$id);self::assertSame(0.0,$r['payload']['values'][$fields[0]['id']]);self::assertFalse($r['payload']['values'][$fields[1]['id']]);
  $t->archiveField($a,(int)$fields[0]['id']);unset($values[$fields[0]['id']]);$s->update($a,$id,['title'=>'Asset updated','payload'=>['template_id'=>$type,'values'=>$values]]);self::assertSame(0.0,$s->get($a,$id)['payload']['values'][$fields[0]['id']]);self::assertSame(1,(int)$t->get($type)['fields'][0]['archived']);
 }
 public function testInvalidValuesAndMissingRequiredFields(): void {
  $v=new FieldValidator();foreach([['url','javascript:alert(1)'],['date','2026-02-31'],['number','hello'],['choice','Other'],['boolean','maybe']] as [$type,$value]){try{$v->validate([['id'=>1,'field_type'=>$type,'name'=>'Field','required'=>1,'options'=>'["Basic"]','archived'=>0]],[1=>$value]);self::fail('Invalid value accepted');}catch(\SimpleMSPDoc\Core\HttpException $e){self::assertSame(422,$e->status);}}
 }
 public function testArchivedValuesAreRemovedFromClientSearch(): void {
  $this->schema();$a=new Actor($this->user(),'administrator','staff');$c=new Actor($this->user('read-only','client'),'read-only','client');$org=$this->org();$this->db->run('INSERT INTO user_organizations VALUES (?,?)',[$c->id,$org]);$audit=new AuditService($this->db);$t=new TemplateService($this->db,$audit);$type=$t->create($a,['name'=>'Sensitive legacy fields','fields'=>[['name'=>'Old field','type'=>'text']]]);$field=$t->get($type)['fields'][0]['id'];$s=new AssetService($this->db,$audit);$s->create($a,$org,['title'=>'Shared asset','visibility'=>'client','payload'=>['template_id'=>$type,'values'=>[$field=>'Old sensitive value']]]);$search=new \SimpleMSPDoc\Modules\Search\SearchService($this->db);self::assertSame(1,$search->search($c,'Old sensitive value',null,null,1)['total']);$t->archiveField($a,(int)$field);self::assertSame(0,$search->search($c,'Old sensitive value',null,null,1)['total']);$s->update($a,(int)$this->db->one("SELECT id FROM records WHERE type='asset'")['id'],['title'=>'Shared asset','visibility'=>'client','payload'=>['template_id'=>$type,'values'=>[]]]);self::assertSame(0,$search->search($c,'Old sensitive value',null,null,1)['total']);
 }

 public function testStandardDetailsAndColumnPreferencesPreserveScope(): void {
  $this->schema();$a=new Actor($this->user(),'administrator','staff');$org=$this->org();$audit=new AuditService($this->db);$t=new TemplateService($this->db,$audit);$type=$t->create($a,['name'=>'Devices']);$service=new AssetService($this->db,$audit);
  $id=$service->create($a,$org,['title'=>'Laptop','payload'=>['template_id'=>$type,'details'=>['serial_number'=>'ABC','device_type'=>'Laptop','ram'=>'32 GB','purchase_date'=>'2026-10-01','warranty_expiration'=>'2029-10-01','mac_address'=>'aa:bb:cc:dd:ee:ff']]]);
  $r=$service->get($a,$id);self::assertSame('ABC',$r['payload']['details']['serial_number']);self::assertStringContainsString('ABC',$this->db->one('SELECT search_text FROM records WHERE id=?',[$id])['search_text']);
  $columns=new \SimpleMSPDoc\Modules\Assets\ConfigurationTable($this->db);$available=$columns->available($a,$org);self::assertArrayHasKey('serial_number',$available);$columns->save($a,$org,['title','serial_number','ram']);self::assertSame(['title','serial_number','ram'],$columns->selected($a,$org,$available));
  $other=new Actor($this->user(),'administrator','staff');self::assertSame(['title','category','visibility','updated_at'],$columns->selected($other,$org,$available));
  $this->db->run('UPDATE configuration_preferences SET columns_json=? WHERE user_id=? AND organization_id=?',[json_encode(['title','serial_number','serial_number']),$a->id,$org]);self::assertSame(['title','serial_number'],$columns->selected($a,$org,$available));
  $this->expectException(\SimpleMSPDoc\Core\HttpException::class);$service->update($a,$id,['title'=>'Laptop','payload'=>['template_id'=>$type,'details'=>['purchase_date'=>'2026-02-30']]]);
 }
 public function testConfigurationColumnsDoNotExposeInternalContactsToClients(): void {
  $this->schema();$a=new Actor($this->user(),'administrator','staff');$c=new Actor($this->user('read-only','client'),'read-only','client');$org=$this->org();$other=$this->org('Unassigned');$this->db->run('INSERT INTO user_organizations VALUES (?,?)',[$c->id,$org]);$audit=new AuditService($this->db);$type=(new TemplateService($this->db,$audit))->create($a,['name'=>'Shared template']);$contact=(new \SimpleMSPDoc\Modules\Organizations\ContactService($this->db,$audit))->create($a,$org,['title'=>'Secret internal contact']);$s=new AssetService($this->db,$audit);$id=$s->create($a,$org,['title'=>'Shared device','visibility'=>'client','payload'=>['template_id'=>$type,'contact_id'=>$contact]]);$table=new \SimpleMSPDoc\Modules\Assets\ConfigurationTable($this->db);$cells=$table->cells($c,[$s->get($c,$id)]);self::assertSame('',$cells[$id]['contact_id']);self::assertSame('Secret internal contact',$table->cells($a,[$s->get($a,$id)])[$id]['contact_id']);
  $custom=new TemplateService($this->db,$audit);$custom->addField($a,$type,['name'=>'Archived device field','type'=>'text']);$field=(int)$custom->get($type)['fields'][0]['id'];$s->archive($a,$id);self::assertArrayHasKey('field_'.$field,$table->available($a,$org));
  $this->expectException(\SimpleMSPDoc\Core\HttpException::class);$table->save($c,$other,['title']);
 }
 public function testSharedSourcesMergeDeterministicallyAndManualNotesSurviveSync(): void {
  $this->schema();$a=new Actor($this->user(),'administrator','staff');$org=$this->org();$audit=new AuditService($this->db);$type=(new TemplateService($this->db,$audit))->create($a,['name'=>'Shared device']);$s=new AssetService($this->db,$audit);$id=$s->create($a,$org,['title'=>'PC','payload'=>['template_id'=>$type,'details'=>['manufacturer'=>'Manual vendor'],'notes'=>'Local notes']]);
  $s->setSourceDetails($a,$id,'action1',['manufacturer'=>'Dell','ram'=>'32 GB'],'Remote notes');$s->setSourceDetails($a,$id,'second',['manufacturer'=>'HP','model'=>'Model 1'],'Remote notes');$p=$s->get($a,$id)['payload'];$details=\SimpleMSPDoc\Modules\Assets\ConfigurationDetails::effective($p);self::assertSame('Manual vendor',$details['manufacturer']);self::assertSame('32 GB',$details['ram']);self::assertSame('Model 1',$details['model']);self::assertSame("Local notes\n\nRemote notes",\SimpleMSPDoc\Modules\Assets\ConfigurationDetails::notes($p));
  $s->setSourceDetails($a,$id,'action1',['ram'=>'48 GB'],'Refreshed notes');$p=$s->get($a,$id)['payload'];self::assertSame("Local notes\n\nRefreshed notes\n\nRemote notes",\SimpleMSPDoc\Modules\Assets\ConfigurationDetails::notes($p));$p['notes']=\SimpleMSPDoc\Modules\Assets\ConfigurationDetails::notes($p);$s->update($a,$id,['title'=>'PC','payload'=>$p]);self::assertSame('Local notes',$s->get($a,$id)['payload']['notes']);
  $p=$s->get($a,$id)['payload'];$p['notes']="Local notes edited\n\nRefreshed notes\n\nRemote notes";$s->update($a,$id,['title'=>'PC','payload'=>$p]);$s->setSourceDetails($a,$id,'action1',['ram'=>'64 GB'],'New source note');$p=$s->get($a,$id)['payload'];self::assertSame("Local notes edited\n\nNew source note\n\nRemote notes",\SimpleMSPDoc\Modules\Assets\ConfigurationDetails::notes($p));
  $p['notes']='Entirely manual notes';$s->update($a,$id,['title'=>'PC','payload'=>$p]);$s->setSourceDetails($a,$id,'action1',[],'Another source note');self::assertSame('Entirely manual notes',\SimpleMSPDoc\Modules\Assets\ConfigurationDetails::notes($s->get($a,$id)['payload']));

 }
 public function testLegacyManualFieldsBeatSourcesAndUnifiedEditsRespectValidation(): void {
  $this->schema();$a=new Actor($this->user(),'administrator','staff');$audit=new AuditService($this->db);$org=$this->org();$templates=new TemplateService($this->db,$audit);$type=$templates->create($a,['name'=>'Manual legacy','fields'=>[['name'=>'Serial number','type'=>'text','required'=>true],['name'=>'RAM','type'=>'number'],['name'=>'Manufacturer','type'=>'choice','options'=>['Dell','HP']]]]);$f=$templates->get($type)['fields'];$s=new AssetService($this->db,$audit);$id=$s->create($a,$org,['title'=>'Legacy','payload'=>['template_id'=>$type,'values'=>[$f[0]['id']=>'MANUAL',$f[1]['id']=>16,$f[2]['id']=>'Dell']]]);$s->setSourceDetails($a,$id,'action1',['serial_number'=>'REMOTE']);$p=$s->get($a,$id)['payload'];self::assertSame('MANUAL',\SimpleMSPDoc\Modules\Assets\ConfigurationDetails::effective($p,$f)['serial_number']);
  foreach([['serial_number'=>''],['ram'=>'not a number'],['manufacturer'=>'Other']] as $details){try{$s->update($a,$id,['title'=>'Legacy','payload'=>['template_id'=>$type,'details'=>$details]]);self::fail('Invalid canonical edit accepted');}catch(\SimpleMSPDoc\Core\HttpException $e){self::assertSame(422,$e->status);}}
 }
 public function testMergedEditorCanRemoveOnlySourceNotes(): void {
  $old=['notes'=>'Local','source_notes'=>['action1'=>'Remote']];[$notes,$overrides]=\SimpleMSPDoc\Modules\Assets\ConfigurationDetails::editNotes('Local',$old,[],true);self::assertSame('Local',$notes);self::assertSame('Local',\SimpleMSPDoc\Modules\Assets\ConfigurationDetails::notes(['notes'=>$notes,'source_notes'=>$old['source_notes'],'note_overrides'=>$overrides]));
  [$notes,$overrides]=\SimpleMSPDoc\Modules\Assets\ConfigurationDetails::editNotes('',['notes'=>'','source_notes'=>['action1'=>'Remote']],[],true);self::assertSame('',\SimpleMSPDoc\Modules\Assets\ConfigurationDetails::notes(['notes'=>$notes,'source_notes'=>['action1'=>'Remote'],'note_overrides'=>$overrides]));
 }
 public function testUnchangedImportedValueDoesNotBecomeLegacyManualOverride(): void {
  $this->schema();$a=new Actor($this->user(),'administrator','staff');$audit=new AuditService($this->db);$templates=new TemplateService($this->db,$audit);$type=$templates->create($a,['name'=>'Empty legacy','fields'=>[['name'=>'Serial number','type'=>'text']]]);$fields=$templates->get($type)['fields'];$s=new AssetService($this->db,$audit);$id=$s->create($a,$this->org(),['title'=>'PC','payload'=>['template_id'=>$type]]);$s->setSourceDetails($a,$id,'second',['serial_number'=>'REMOTE']);$s->update($a,$id,['_notes_are_merged'=>true,'title'=>'PC','payload'=>['template_id'=>$type,'details'=>['serial_number'=>'REMOTE']]]);$s->setSourceDetails($a,$id,'second',['serial_number'=>'REMOTE2']);self::assertSame('REMOTE2',\SimpleMSPDoc\Modules\Assets\ConfigurationDetails::effective($s->get($a,$id)['payload'],$fields)['serial_number']);
 }
 public function testMergedNotesCanExceedLegacyTextFieldLimit(): void {
  $this->schema();$a=new Actor($this->user(),'administrator','staff');$audit=new AuditService($this->db);$templates=new TemplateService($this->db,$audit);$type=$templates->create($a,['name'=>'Legacy short notes','fields'=>[['name'=>'Action1 notes','type'=>'text','required'=>true]]]);$field=$templates->get($type)['fields'][0]['id'];$s=new AssetService($this->db,$audit);$manual=str_repeat('M',700);$source=str_repeat('S',700);$id=$s->create($a,$this->org(),['title'=>'PC','payload'=>['template_id'=>$type,'values'=>[$field=>$source],'notes'=>$manual]]);$s->update($a,$id,['_notes_are_merged'=>true,'title'=>'PC','payload'=>['template_id'=>$type,'notes'=>$manual."\n\n".$source]]);$p=$s->get($a,$id)['payload'];self::assertSame($manual,$p['notes']);self::assertSame($source,$p['values'][$field]);$long=str_repeat('N',1500);$new=$s->create($a,$this->org('New'),['_notes_are_merged'=>true,'title'=>'New','payload'=>['template_id'=>$type,'notes'=>$long]]);$p=$s->get($a,$new)['payload'];self::assertSame($long,\SimpleMSPDoc\Modules\Assets\ConfigurationDetails::notes($p,$templates->get($type)['fields']));
 }
}
